function findMinFibonacciNumbers(k) {
  // Exhaustive coin search: decide how many copies of each distinct Fibonacci value to use, largest first.
  const coins = [1, 2];
  while (coins[coins.length - 1] + coins[coins.length - 2] <= k) coins.push(coins[coins.length - 1] + coins[coins.length - 2]);
  let best = k;
  const seen = new Map();
  function search(index, rest, used) {
    if (rest === 0) { if (used < best) best = used; return; }
    if (index < 0) return;
    const coin = coins[index];
    // Every remaining coin is at most `coin`, so at least ceil(rest / coin) more are needed.
    if (used + Math.ceil(rest / coin) >= best) return;
    // The same (index, rest) reached earlier with no more coins cannot lead anywhere new.
    const key = rest * 64 + index;
    if (seen.has(key) && seen.get(key) <= used) return;
    seen.set(key, used);
    for (let take = Math.floor(rest / coin); take >= 0; take--) search(index - 1, rest - take * coin, used + take);
  }
  search(coins.length - 1, k, 0);
  return best;
}

