function generate(rand, size) {
  const fibs = [1, 2];
  while (fibs[fibs.length - 1] + fibs[fibs.length - 2] <= 1e9) fibs.push(fibs[fibs.length - 1] + fibs[fibs.length - 2]);
  const limit = size === 'large' ? 1e9 : 300;
  const style = rand();
  if (size === 'large' && style < 0.15) return [1e9 - Math.floor(rand() * 5)];
  if (style < 0.4) {
    const usable = fibs.filter(f => f + 1 <= limit);
    const pick = usable[Math.floor(rand() * usable.length)];
    return [Math.max(1, pick + Math.floor(rand() * 3) - 1)];
  }
  const low = size === 'large' ? 1e8 : 1;
  return [low + Math.floor(rand() * (limit - low + 1))];
}
